51:         } else if (coordinates.length) {
52:           const [individual] = coordinates;
53:           map.jumpTo({
54:             center: individual,
55:             zoom: Math.max(defaultZoom > 0 ? defaultZoom : map.getZoom(), 10),
56:           });
57:           setInitialized(true);
58:         }
59:       }
60:     }
61:   }, [
62:     selectedDeviceId,
63:     initialized,
64:     defaultLatitude,
65:     defaultLongitude,
66:     defaultZoom,
67:     positions,
68:     filteredPositions,
69:   ]);
