56:   const [sentinel, setSentinel] = useState(null);
57:   const loadingRef = useRef(false);
58:   const loadMoreRef = useRef(loadMore);
59:   loadMoreRef.current = loadMore;
60: 
61:   useEffect(() => {
62:     if (!sentinel) return undefined;
63:     const observer = new IntersectionObserver(([entry]) => {
64:       if (entry.isIntersecting && !loadingRef.current) {
65:         loadingRef.current = true;
66:         Promise.resolve(loadMoreRef.current?.()).finally(() => {
67:           loadingRef.current = false;
68:         });
69:       }
70:     });
71:     observer.observe(sentinel);
72:     return () => observer.disconnect();
73:   }, [sentinel]);
74: 
75:   return setSentinel;
