34:       const liveRoutes =
35:         state.user.attributes.mapLiveRoutes || state.server.attributes.mapLiveRoutes || 'none';
36:       const liveRoutesLimit =
37:         state.user.attributes['web.liveRouteLength'] ||
38:         state.server.attributes['web.liveRouteLength'] ||
39:         10;
